#include "shared/sea_nuclear_wave.hpp"
#include <algorithm>
#include <cmath>
#include <cstdio>
#include <vector>
using namespace std;
static SeaNuclearWaveSample sample(const vector<SeaNuclearWave>&w,float x,float z){SeaNuclearWaveSample r;for(auto &a:w){auto q=EvaluateSeaNuclearWave(a,x,z);r.height+=q.height;r.slopeX+=q.slopeX;r.slopeZ+=q.slopeZ;r.foam=max(r.foam,q.foam);r.load=max(r.load,q.load);}CompressSeaNuclearWaveSample(r);return r;}
static SeaNuclearWaveSample interp(const vector<SeaNuclearWave>&w,float x,float z){float left=floor(x/48)*48,bottom=floor(z/48)*48,u=(x-left)/48,v=(z-bottom)/48;auto a=sample(w,left,bottom),b=sample(w,left+48,bottom),c=sample(w,left,bottom+48),d=sample(w,left+48,bottom+48);auto mix=[&](float aa,float bb,float cc,float dd){return (aa*(1-u)+bb*u)*(1-v)+(cc*(1-u)+dd*u)*v;};return {mix(a.height,b.height,c.height,d.height),mix(a.slopeX,b.slopeX,c.slopeX,d.slopeX),mix(a.slopeZ,b.slopeZ,c.slopeZ,d.slopeZ),mix(a.foam,b.foam,c.foam,d.foam),mix(a.load,b.load,c.load,d.load)};}
int main(){for(int blasts: {1,4}){double sq=0,qs=0;float maxErr=0,maxSlope=0,maxFoam=0,peak=0;int missed=0,falsepositive=0,count=0;for(int frame=0;frame<120;frame++){float t=frame*.125f;vector<SeaNuclearWave>w;for(int i=0;i<blasts;i++){SeaNuclearWave a{float(i*160),float((i%2)*160),0,0,true,1};a.Advance(t);w.push_back(a);}for(int iz=0;iz<6;iz++)for(int ix=0;ix<6;ix++){float x=420+(ix-2.5f)*8+frame*.15f,z=(iz-2.5f)*4;auto a=sample(w,x,z); float t0=floor(t*10.f)*.1f, phase=(t-t0)*10.f; vector<SeaNuclearWave> w0,w1; for(int k=0;k<blasts;k++){SeaNuclearWave q{float(k*160),float((k%2)*160),0,0,true,1}; q.Advance(t0);w0.push_back(q);q.Advance(.1f);w1.push_back(q);} auto p0=interp(w0,x,z),p1=interp(w1,x,z); SeaNuclearWaveSample b{p0.height*(1-phase)+p1.height*phase,p0.slopeX*(1-phase)+p1.slopeX*phase,p0.slopeZ*(1-phase)+p1.slopeZ*phase,p0.foam*(1-phase)+p1.foam*phase,p0.load*(1-phase)+p1.load*phase};float e=abs(a.height-b.height);sq+=e*e;qs+=a.height*a.height;maxErr=max(maxErr,e);maxSlope=max(maxSlope,hypotf(a.slopeX-b.slopeX,a.slopeZ-b.slopeZ));maxFoam=max(maxFoam,abs(a.foam-b.foam));peak=max(peak,abs(a.height));missed+=(abs(a.height)>.1f&&abs(b.height)<.01f);falsepositive+=(abs(a.height)<.01f&&abs(b.height)>.1f);count++;}}printf("blasts=%d samples=%d height_rmse=%.5f signal_rms=%.5f height_max_error=%.5f signal_peak=%.5f slope_max_error=%.5f foam_max_error=%.5f missed_10cm=%d false_10cm=%d\n",blasts,count,sqrt(sq/count),sqrt(qs/count),maxErr,peak,maxSlope,maxFoam,missed,falsepositive);}}
